    <script>
        // --- Carousel Logic ---
        const track = document.getElementById('track');
        function scrollCarousel(dir) {
            const scrollAmount = 280; // Approx card width + gap
            track.scrollBy({ left: dir * scrollAmount, behavior: 'smooth' });
        }

        // --- Magnifier Logic ---
        const lens = document.getElementById('magnifier-lens');
        const magnification = 1.8; // Zoom factor
        let isHoveringCard = false;

        document.addEventListener('mousemove', (e) => {
            // Check if mouse is over a project card
            const target = e.target.closest('.project-card');

            if (target) {
                isHoveringCard = true;
                lens.style.opacity = '1';

                // Position lens
                lens.style.left = (e.clientX - 70) + 'px'; // Center it
                lens.style.top = (e.clientY - 70) + 'px';

                // Clone content for magnification effect
                // To keep it performant and simple for this demo, we use a CSS transform approach on a clone
                if (lens.children.length === 0 || lens.dataset.target !== target.id) {
                    lens.innerHTML = '';
                    lens.dataset.target = target.id || 'temp';

                    const clone = target.cloneNode(true);
                    clone.style.width = (target.offsetWidth * magnification) + 'px';
                    clone.style.height = (target.offsetHeight * magnification) + 'px';
                    clone.style.transform = `scale(${magnification})`;
                    clone.style.transformOrigin = 'center center';
                    // We need to offset the clone inside the lens based on mouse pos relative to card

                    lens.appendChild(clone);
                }

                // Calculate offsets to move the background image inside the lens
                const clone = lens.firstChild;
                if(clone) {
                    const rect = target.getBoundingClientRect();
                    // Calculate relative position of mouse within the card (0 to 1)
                    const xRel = (e.clientX - rect.left) / rect.width;
                    const yRel = (e.clientY - rect.top) / rect.height;

                    // Adjust transform origin or position to simulate panning
                    // Simple way: move the cloned element inversely
                    // Center of lens is 70px.
                    // We want the point under mouse to be at center of lens.

                    // Let's reset transform and just use absolute positioning math? 
                    // Easier visual hack:
                    // Scale up the clone, then shift it so the mouse coordinate matches.

                    const offsetX = -(xRel * clone.offsetWidth) + 70;
                    const offsetY = -(yRel * clone.offsetHeight) + 70;

                    clone.style.position = 'absolute';
                    clone.style.left = offsetX + 'px';
                    clone.style.top = offsetY + 'px';
                    clone.style.transform = `scale(${magnification})`; // Keep scale
                    // Note: This is a simplified approximation. A true magnifier would capture the render stream.
                }

            } else {
                isHoveringCard = false;
                lens.style.opacity = '0';
            }
        });
    </script>
